import { afterEach, describe, expect, it, vi } from "vitest";

import { writeError, writeOutput } from "./output.js";

describe("output", () => {
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("writes a serialized Error", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const error = new TypeError("Something went wrong");
		error.stack = "TypeError: Something went wrong\n    at worker.ts:1:1";

		writeError(error);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify({ name: error.name, message: error.message, stacktrace: error.stack })}</__notion_error__>\n`,
		);
	});

	it("includes a serialized Error cause", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const cause = new RangeError("Root failure");
		cause.stack = "RangeError: Root failure\n    at dependency.ts:1:1";
		const error = new TypeError("Something went wrong", { cause });
		error.stack = "TypeError: Something went wrong\n    at worker.ts:1:1";

		writeError(error);

		const serializedCause = {
			name: cause.name,
			message: cause.message,
			stacktrace: cause.stack,
		};
		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify({
				name: error.name,
				message: error.message,
				stacktrace: error.stack,
				cause: serializedCause,
			})}</__notion_error__>\n`,
		);
	});

	it("JSON-stringifies a non-Error cause", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const cause = { reason: "Root failure" };
		const error = new Error("Something went wrong", { cause });
		delete error.stack;

		writeError(error);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify({
				name: error.name,
				message: error.message,
				cause,
			})}</__notion_error__>\n`,
		);
	});

	it("handles a circular Error cause", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const error = new Error("Something went wrong");
		delete error.stack;
		error.cause = error;
		const serializedError = {
			name: error.name,
			message: error.message,
			cause: "[Circular Error]",
		};

		writeError(error);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify(serializedError)}</__notion_error__>\n`,
		);
	});

	it("only writes the JSON value when the caught value is not an Error", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const value = { reason: "Something went wrong" };

		writeError(value);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify(value)}</__notion_error__>\n`,
		);
	});

	it("omits the stacktrace key when an Error has no stack", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const error = new Error("Something went wrong");
		delete error.stack;

		writeError(error);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_error__>${JSON.stringify({ name: error.name, message: error.message })}</__notion_error__>\n`,
		);
	});

	it("escapes tag delimiters in error values", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const error = new Error("Failed </__notion_error_message__> & retry");
		error.stack = "Error: Failed </__notion_error_stacktrace__> & retry";

		writeError(error);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			'\n<__notion_error__>{"name":"Error","message":"Failed &lt;/__notion_error_message__&gt; &amp; retry","stacktrace":"Error: Failed &lt;/__notion_error_stacktrace__&gt; &amp; retry"}</__notion_error__>\n',
		);
	});

	it("writes output without inspecting it for errors", () => {
		const stdoutSpy = vi.spyOn(process.stdout, "write").mockImplementation(() => true);
		const value = { _tag: "error", error: { message: "Something went wrong" } };

		writeOutput(value);

		expect(stdoutSpy).toHaveBeenCalledExactlyOnceWith(
			`\n<__notion_output__>${JSON.stringify(value)}</__notion_output__>\n`,
		);
	});
});
